def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'

# ---- numbers (recomputed) ----
G=20*18            # L/h CO2 from 20 people at 18 L/h each (typical sedentary value, example)
Q=G/400e-6/1000    # m3/h for dC = 400 ppm
assert G==360 and round(Q)==900 and round(Q/20)==45 and round(45*40)==1800
assert round(0.3**3,3)==0.027 and round(0.25**3,4)==0.0156 and round(0.5**3,3)==0.125                     # fan at 50% speed -> 12.5% power
Tout,Tin,eta=-10,22,0.7
Tafter=Tout+eta*(Tin-Tout);assert round(Tafter,1)==12.4
assert round((20-Tout)-(20-Tafter),1)==22.4 and round(22.4/30*100,1)==74.7
assert round(2/(4.19*5)*3600)==344 and round(20/(4.19*5)*3600,-1)==3440 and round(10/(4.19*5)*3600,-1)==1720 and 3.5+1.0==4.5 and 3.5/1.0==3.5 and 600+300+300==1200 and round(1200/1800,3)==0.667 and round((1200/1800)**3,2)==0.30
assert 400e-6*1e6==400 and 800/1e6*100==0.08

